// Spike 7: theme color resolution — schemeClr -> actual RGB.
// The promised differentiator (python-pptx cannot do this), and the probe
// for what belongs in the shared "dml" package vs the pptx layer.
// Three acts:
//  A) pure color math against PowerPoint's own UI values for the standard
//     Office accent1 variants ("Lighter 40%" etc.);
//  B) full chain resolution (slide -> layout -> master -> theme + clrMap)
//     on both real fixtures, including sysClr and tint;
//  C) cross-validation on a deck generated by python-pptx with theme colors
//     set through its own API (07-generate.py).
import { readFile } from "node:fs/promises";
import { resolveColor } from "./packages/dml/index.mjs";
import { Presentation } from "./packages/pptx/index.mjs";
import { parseXml, walk, attrsOf, tagOf, el } from "./packages/xml/index.mjs";

let failures = 0;
const near = (a, b, tol = 1) => {
  const ch = (h, i) => parseInt(h.slice(i * 2, i * 2 + 2), 16);
  return [0, 1, 2].every((i) => Math.abs(ch(a, i) - ch(b, i)) <= tol);
};
function check(label, actual, expected, exact = false) {
  const ok = exact ? actual === expected : near(actual, expected);
  if (!ok) failures++;
  console.log(`  ${ok ? "ok " : "FAIL"} ${label}: ${actual} (expected ${expected}${exact ? "" : " ±1/channel"})`);
}

// --- Act A: color math vs PowerPoint UI values -----------------------------
// Office theme accent1 #4472C4 and the values PowerPoint's color picker shows.
console.log("Act A: lumMod/lumOff math vs PowerPoint's accent1 variants");
{
  const scheme = { accent1: "4472C4" };
  const mk = (transforms) =>
    resolveColor(el("a:schemeClr", { val: "accent1" }, transforms), (n) => scheme[n]).hex;
  check("base", mk([]), "4472C4", true);
  check("Lighter 60% (lumMod 40k, lumOff 60k)", mk([el("a:lumMod", { val: "40000" }), el("a:lumOff", { val: "60000" })]), "B4C7E7");
  check("Lighter 40% (lumMod 60k, lumOff 40k)", mk([el("a:lumMod", { val: "60000" }), el("a:lumOff", { val: "40000" })]), "8EAADB");
  check("Darker 25% (lumMod 75k)", mk([el("a:lumMod", { val: "75000" })]), "2F5496");
  check("Darker 50% (lumMod 50k)", mk([el("a:lumMod", { val: "50000" })]), "1F3864");
}

// --- Act B: full chain on real fixtures -------------------------------------
console.log("\nAct B: slide -> layout -> master -> theme chain on fixtures");
{
  const pres = Presentation.open(new Uint8Array(await readFile("../tests/fixtures/Psalm 134 (DNP) wit copy 100.pptx")));
  const ctx = pres.slides[0].colorContext();
  console.log(`  theme: ${ctx.themePart}, accent1=${ctx.scheme.accent1}, clrMap bg1->${ctx.clrMap.bg1}`);
  const rgb = (name) => ctx.resolve(el("a:schemeClr", { val: name })).hex;
  check("accent1 (direct)", rgb("accent1"), "00CC99", true);
  check("tx1 -> clrMap -> dk1", rgb("tx1"), "000000", true);
  check("bg2 -> clrMap -> lt2", rgb("bg2"), "808080", true);
}
{
  const pres = Presentation.open(new Uint8Array(await readFile("../tests/fixtures/hagar-presentatie.pptx")));
  const ctx = pres.slides[0].colorContext();
  // dk1 is a:sysClr windowText with lastClr="000000" -> sysClr path.
  check("tx1 -> dk1 via sysClr lastClr", ctx.resolve(el("a:schemeClr", { val: "tx1" })).hex, "000000", true);
  // The master uses tx1 with tint 75000 (black tinted 75% toward white keeps 25% -> 3F/40).
  check("tx1 + tint 75%", ctx.resolve(el("a:schemeClr", { val: "tx1" }, [el("a:tint", { val: "75000" })])).hex, "404040");

}
{
  // Sweep both fixtures: every schemeClr on every slide, layout and master
  // must resolve — nothing may throw or return null.
  for (const file of ["hagar-presentatie.pptx", "Psalm 134 (DNP) wit copy 100.pptx"]) {
    const pres = Presentation.open(new Uint8Array(await readFile(`../tests/fixtures/${file}`)));
    const c = pres.slides[0].colorContext();
    let n = 0;
    const parts = pres.package.partNames.filter((p) => /^ppt\/(slides|slideLayouts|slideMasters)\/[^_]/.test(p));
    for (const part of parts) {
      for (const node of walk(parseXml(pres.package.read(part)), "a:schemeClr")) {
        if (attrsOf(node).val === "phClr") continue; // placeholder color: caller-supplied, not theme
        if (!c.resolve(node)) throw new Error(`unresolvable schemeClr on ${part}`);
        n++;
      }
    }
    console.log(`  ok  sweep ${file}: ${n} schemeClr nodes across ${parts.length} parts all resolved`);
  }
}

// --- Act C: cross-validation against python-pptx-authored theme colors ------
console.log("\nAct C: deck authored by python-pptx (theme_color + brightness API)");
{
  const pres = Presentation.open(new Uint8Array(await readFile("out/spike7-themed.pptx")));
  const slide = pres.slides[0];
  const ctx = slide.colorContext();
  const runs = [];
  for (const shape of slide.shapes()) {
    for (const node of walk(parseXml(pres.package.read(slide.partName)), "a:schemeClr")) {
      runs.push(node);
    }
    break; // one shape, its runs carry the schemeClr nodes in document order
  }
  // Run 1: theme_color = ACCENT_1 -> must equal the theme's accent1 exactly.
  check("python-pptx ACCENT_1", ctx.resolve(runs[0]).hex, ctx.scheme.accent1, true);
  // Run 2: ACCENT_1 + brightness 0.4 -> python-pptx writes lumMod 60k + lumOff 40k.
  // python-pptx's default template carries the Office 2007 theme (accent1
  // 4F81BD); PowerPoint's UI value for its "Lighter 40%" variant is 95B3D7.
  const t2 = [...(runs[1][tagOf(runs[1])] ?? [])].map((c) => tagOf(c));
  console.log(`  python-pptx wrote for brightness 0.4: ${t2.join(", ")}`);
  check("python-pptx ACCENT_1 brightness 0.4", ctx.resolve(runs[1]).hex, "95B3D7");
}

console.log(failures ? `\n${failures} FAILURES` : "\nSPIKE 7 PASSED");
process.exit(failures ? 1 : 0);
